/**
 * @file Content collections — the single source of truth for site content.
 * @module content.config
 */
import { defineCollection } from 'astro:content';
import { file, glob } from 'astro/loaders';
import { z } from 'astro/zod';
import * as yaml from 'js-yaml';

// Generated by scripts/sync-projects.mjs from your pinned GitHub repos.
// Don't edit by hand — changes are overwritten on the next sync.
const projects = defineCollection({
  loader: file('src/data/projects.json'),
  schema: z.object({
    name: z.string(),
    github: z.url().optional(),
    demo: z.url().optional(),
    tech: z.array(z.string()),
    status: z.string(),
    summary: z.string(),
    whyItMatters: z.string().optional(),
    readmeSha: z.string().nullable(),
    order: z.number(),
  }),
});

// Hand-written corrections, keyed by GitHub repo name. Every field is optional
// and wins over the generated value.
const projectOverrides = defineCollection({
  // A file with only comments parses to nothing; treat it as "no overrides".
  loader: file('src/data/overrides.yml', { parser: (text) => yaml.load(text) ?? {} }),
  schema: z.object({
    name: z.string().optional(),
    demo: z.url().optional(),
    tech: z.array(z.string()).optional(),
    status: z.string().optional(),
    summary: z.string().optional(),
    whyItMatters: z.string().optional(),
    order: z.number().optional(),
    hidden: z.boolean().default(false),
  }),
});

// Career milestones shown by `git log` in the terminal, keyed by any short id.
// Entries without a date are skipped.
const timeline = defineCollection({
  loader: file('src/data/timeline.yml', { parser: (text) => yaml.load(text) ?? {} }),
  schema: z.object({
    date: z.string().regex(/^\d{4}(-\d{2}){0,2}$/, 'Use YYYY, YYYY-MM or YYYY-MM-DD').optional(),
    message: z.string(),
  }),
});

// Blog posts: one Markdown file per post in src/content/blog/, the filename is
// the URL (`my-post.md` → /blog/my-post/). Files starting with `_` are ignored.
// Format and examples: docs/blog-post-template.md.
const TAG = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const blog = defineCollection({
  loader: glob({ pattern: '**/[^_]*.md', base: './src/content/blog' }),
  schema: z.object({
    title: z.string().min(1),
    description: z.string().min(1).max(200, 'Keep the description to one sentence (200 characters at most)'),
    date: z.coerce.date(),
    updated: z.coerce.date().optional(),
    tags: z.array(z.string().regex(TAG, 'Tags are lowercase words joined by dashes, like "rust" or "system-design"')).default([]),
    // GitHub repo name of the related project (the key in src/data/projects.json).
    project: z.string().optional(),
    draft: z.boolean().default(false),
  }),
});

export const collections = { projects, projectOverrides, timeline, blog };
